/* v16.xx (cw-menupolish2): THE GAMBLE panel: a 192px mystery tile (the offer picture's size) over the odds, one row a rarity: name in its colour, a 6px bar, the percent */
#root #gamblemodal #gambleodds{flex:none;display:flex;flex-direction:column;align-items:stretch;gap:var(--sp-3);width:100%;}
