     for(i=0;i<GAMBLE_POOL.length;i++){ k=GAMBLE_POOL[i][0]; r=(k==='KEY')?'rare':((typeof dispR==='function'&&dispR(k))||(ITEMS[k]&&ITEMS[k].r)||'common'); by[r]=(by[r]||0)+(+GAMBLE_POOL[i][1]||0); tot+=(+GAMBLE_POOL[i][1]||0); }
